function CLIQUE_COMPLEX(G = (V, E)):
    faces <- {}
    for each subset s of V (in increasing size):
        if for all distinct u,v in s: {u,v} in E:
            faces <- faces union {s}
    return faces

function ONE_SKELETON(V, K):
    edges <- {}
    for each pair {u,v} with u != v in V:
        if {u,v} in K:
            edges <- edges union {{u,v}}
    return (V, edges)

function VR_FILTRATION(V, d):
    scales <- sorted distinct values { d(u,v) : u != v }
    filtration <- []
    for eps in scales:
        edges <- { {u,v} : u != v and d(u,v) <= eps and d(v,u) <= eps }
        K <- CLIQUE_COMPLEX((V, edges))
        filtration.append((eps, K))
    return filtration   # piecewise-constant; constant between scales

